+\lhead{DJAMEL BENMAKHLOUF}
+\rhead{Terminale Spécialité Mathématiques}
+% Pagination : « Page X / Y » centrée en pied de page
+\usepackage{lastpage}
+\cfoot{Page \thepage\ / \pageref{LastPage}}
+\renewcommand{\headrulewidth}{0.5pt}
+% Trait de séparation éloigné du texte de l'en-tête (modifier 5pt pour ajuster)
+\renewcommand{\headrule}{\vskip 5pt\hrule width\headwidth height\headrulewidth \vskip-\headrulewidth}
+
+% Configuration des listes
+\setlist[enumerate,1]{itemsep=0.45em, topsep=0.3em, label=\textbf{\arabic*.}}
+\setlist[enumerate,2]{itemsep=0.25em, topsep=0.2em, label=\textbf{\alph*.}}
+
+% Commande exercice
+\newcommand{\exo}[2]{%
+  \vspace{1.5em}%
+  \noindent{\large\textbf{Exercice #1. -- #2}}%
+  \par\vspace{0.35em}%
+  \hrule height 0.5pt%
+  \vspace{0.7em}%
+}
+
+\newcommand{\partie}[1]{%
+  \vspace{0.9em}%
+  \noindent\textbf{#1}%
+  \par\vspace{0.3em}%
+}
+
+\begin{document}
+
+\begin{center}
+  {\LARGE \textbf{Calcul intégral et Équations différentielles}}\\[0.5em]
+  {\large Terminale Spécialité Mathématiques}
+\end{center}
+
+% ---------------------- EXERCICE 1 ----------------------
+\exo{1}{Étude d'une fonction, calcul intégral et modélisation}
+
+Soit $f$ la fonction définie sur l'intervalle $[0\,;\,+\infty[$ par :
+\[ f(x) = (2x + 1)\mathrm{e}^{-x} \]
+On note $\mathcal{C}_f$ sa courbe représentative dans un repère orthogonal $(O\,;\, \vec{i}, \vec{j})$.
+
+\partie{Partie A -- Étude de la fonction $f$}
+
+\begin{enumerate}
+  \item Déterminer la limite de la fonction $f$ en $+\infty$ et interpréter graphiquement le résultat obtenu.
+  \item Démontrer que pour tout réel $x \in [0\,;\,+\infty[$, $f'(x) = (1 - 2x)\mathrm{e}^{-x}$.
+  \item Étudier le signe de $f'(x)$ sur $[0\,;\,+\infty[$ et dresser le tableau de variations de la fonction $f$ sur cet intervalle.
+  \item Démontrer que l'équation $f(x) = 1$ admet une unique solution $\alpha$ sur l'intervalle $[0\,;\,1]$ et donner un encadrement de $\alpha$ d'amplitude $10^{-2}$.
+\end{enumerate}
+
+\partie{Partie B -- Calcul intégral et aire}
+
+\begin{enumerate}
+  \item Démontrer que la fonction $F$ définie sur $[0\,;\,+\infty[$ par $F(x) = (-2x - 3)\mathrm{e}^{-x}$ est une primitive de la fonction $f$ sur $[0\,;\,+\infty[$.
+  \item Calculer l'intégrale $I = \int_{0}^{1} f(x)\,\mathrm{d}x$. On donnera la valeur exacte puis une valeur approchée au centième.
+  \item Soit $a$ un réel strictement positif. On considère l'aire $\mathcal{A}(a)$, exprimée en unités d'aire, du domaine délimité par l'axe des abscisses, la courbe $\mathcal{C}_f$ et les droites d'équations $x = 0$ et $x = a$.
+  \begin{enumerate}
+    \item Exprimer $\mathcal{A}(a)$ en fonction de $a$.
+    \item Déterminer la limite de $\mathcal{A}(a)$ lorsque $a$ tend vers $+\infty$.
+  \end{enumerate}
+\end{enumerate}
+
+% ---------------------- EXERCICE 2 ----------------------
+\exo{2}{Équations différentielles et cinétique}
+
+On s'intéresse à la décomposition d'un médicament dans le sang d'un patient. La concentration du médicament, exprimée en mg/L, est modélisée par une fonction $y$ du temps $t$ (en heures). 
+On admet que la fonction $y$ est solution sur $[0\,;\,+\infty[$ de l'équation différentielle :
+\[ (E) \quad : \quad y' + 0{,}2\,y = 1{,}5 \]
+
+\begin{enumerate}
+  \item Résoudre l'équation différentielle homogène associée à $(E)$, c'est-à-dire : $y' + 0{,}2\,y = 0$.
+  \item Démontrer que la fonction constante $y_0$ définie par $y_0(t) = 7{,}5$ est une solution particulière de l'équation $(E)$.
+  \item En déduire l'ensemble de toutes les solutions de l'équation différentielle $(E)$.
+  \item Sachant qu'à l'instant initial $t = 0$, la concentration du médicament injecté est nulle ($y(0) = 0$), déterminer l'expression de la fonction $y(t)$ pour tout $t \ge 0$.
+  \item 
+  \begin{enumerate}
+    \item Étudier le sens de variation de la fonction $y$ sur $[0\,;\,+\infty[$.
+    \item Déterminer la limite de la concentration $y(t)$ lorsque le temps $t$ tend vers $+\infty$ et interpréter ce résultat dans le contexte médical.
