\begin{document}
\begin{center}
  {\LARGE \textbf{Exercice 1 -- Fonction affine}}\\[0.5em]
  {\large Classe de Seconde}
\end{center}

\exo{1}{Fonction affine}

\partie{Partie A -- Propriétés de la fonction affine}
\begin{enumerate}
  \item Démontrer que toute fonction affine $ f(x) = ax + b $ est continue et dérivable sur $\mathbb{R}$.
  \item En déduire que la fonction affine est strictement monotone si et seulement si $ a \neq 0 $.
  \begin{enumerate}
    \item Justifier que la fonction affine est injective si $ a \neq 0 $.
    \item Montrer que la fonction affine est surjective si $ a \neq 0 $.
  \end{enumerate}
\end{enumerate}

\partie{Partie B -- Applications et réciproques}
\begin{enumerate}
  \item Soit $ f $ une fonction affine vérifiant $ f(0) = 2 $ et $ f(1) = 5 $. Déterminer l'équation de $ f $.
  \item Résoudre l'inéquation $ f(x) \leq 0 $ pour $ f(x) = 3x - 2 $.
  \begin{enumerate}
    \item Déterminer le nombre de solutions.
    \item Tracer la représentation graphique des solutions.
  \end{enumerate}
\end{enumerate}
\end{document}

